LM.LAB = {"cases":[{"id":"nominative","name":"Mianownik","nameEn":"Nominative","questions":"kto? co?","level":"A1","summary":"The dictionary form: the subject of the sentence, and the noun after to jest / to są.","uses":[{"label":"Subject","pl":"Anna pracuje w banku.","en":"Anna works at a bank."},{"label":"After to jest / to są","pl":"To jest mój brat.","en":"This is my brother."},{"label":"Adjective after być","pl":"Kawa jest gorąca.","en":"The coffee is hot."},{"label":"Name after nazywać się","pl":"Nazywam się Tomek.","en":"My name is Tomek."},{"label":"Plural: men vs everyone and everything else","pl":"Moi koledzy są mili, a te książki są nowe.","en":"My colleagues are nice, and these books are new."}],"triggers":{"prepositions":[],"verbs":["być + adjective","nazywać się"],"other":["to jest","to są"]},"endings":{"singular":{"masculine":"— (consonant); a few in -a: tata, kolega","feminine":"-a (a few: -i pani, consonant noc)","neuter":"-o / -e / -ę / -um"},"plural":{"masculine personal":"-i / -y / -owie","other":"-y / -i / -e / -a"},"adjective":{"singular":{"masculine":"-y / -i","feminine":"-a","neuter":"-e"},"plural":{"masculine personal":"-i / -y","other":"-e"}}},"traps":["After być a noun goes into the instrumental: Jestem studentem, not Jestem student. With to jest the noun stays in the nominative: To jest student.","Masculine personal plurals change the last consonant: student → studenci, Polak → Polacy. Not studenty, Polaki.","A group with at least one man takes the masculine personal forms: Ania i Tomek są zmęczeni. Animals and children do not: Psy są głodne, Dzieci są małe."],"contrasts":[{"with":"accusative","rule":"The subject is in the nominative. The direct object is in the accusative: feminine nouns change -a to -ę.","examples":["Kawa jest dobra.","Lubię kawę."]}],"topicIds":["a1-cases-nominative","a2-cases-nominative-plural"],"setTags":["nominative"]},{"id":"genitive","name":"Dopełniacz","nameEn":"Genitive","questions":"kogo? czego?","level":"A1","summary":"Absence, possession, quantity, and after many prepositions.","uses":[{"label":"After negation","pl":"Nie mam czasu.","en":"I don't have time."},{"label":"Possession (of whom?)","pl":"To jest samochód Marka.","en":"This is Marek's car."},{"label":"Quantity and containers","pl":"Poproszę butelkę wody.","en":"A bottle of water, please."},{"label":"After do, z, bez, dla, u","pl":"Idę do sklepu.","en":"I'm going to the shop."},{"label":"Plural after dużo, kilka, ile? and 5+","pl":"Na koncercie było dużo ludzi.","en":"There were a lot of people at the concert."},{"label":"Next to, opposite, near","pl":"Poczta jest obok banku.","en":"The post office is next to the bank."}],"triggers":{"prepositions":["do","z (from)","od","bez","dla","u","obok","koło","naprzeciwko","blisko","niedaleko"],"verbs":["szukać","słuchać","używać","bać się","potrzebować","uczyć się (Uczę się polskiego)"],"other":["nie ma","nie mam, nie lubię …","dużo","mało","kilka","pięć i więcej","ile?","nie wolno, nie można + object"]},"endings":{"singular":{"masculine":"-a / -u","feminine":"-y / -i","neuter":"-a"},"plural":{"masculine personal":"-ów / -i / -y","other":"-ów / — / -i / -y"},"adjective":{"singular":{"masculine":"-ego","feminine":"-ej","neuter":"-ego"},"plural":{"masculine personal":"-ych / -ich","other":"-ych / -ich"}}},"traps":["English does not change the object after not, so learners keep the accusative: Nie mam czas ✗ → Nie mam czasu ✓.","Masculine people and animals that end in a consonant always take -a (brata, kota). For things it is -a or -u, and you learn them in pairs (dom – domu, chleb – chleba).","After nie only an object that would be in the accusative changes. The subject stays in the nominative (Kawa nie jest droga), and other cases stay too (Nie pomagam mamie).","After dużo, kilka, ile? and 5+ the noun is genitive plural and the verb is singular: Było dużo ludzi, not Były dużo ludzie.","Feminine and neuter nouns usually lose their last vowel, often with an e added: minuta → minut, piwo → piw, książka → książek. Not książków."],"contrasts":[{"with":"accusative","rule":"A positive sentence takes the accusative. The same sentence with nie takes the genitive.","examples":["Mam samochód.","Nie mam samochodu."]},{"with":"locative","rule":"do + genitive = where to (a shop, a city). w + locative = where you are.","examples":["Jadę do Krakowa.","Mieszkam w Krakowie."]}],"topicIds":["a1-cases-genitive-basics","a2-cases-genitive-plural-quantities"],"setTags":["genitive"]},{"id":"dative","name":"Celownik","nameEn":"Dative","questions":"komu? czemu?","level":"A2","summary":"The person who receives something, after pomagać and dziękować, and the person in podoba mi się and jest mi zimno.","uses":[{"label":"The person who receives","pl":"Daję mamie prezent.","en":"I'm giving Mum a present."},{"label":"After pomagać and dziękować","pl":"Pomagam bratu.","en":"I help my brother."},{"label":"podobać się: the person who likes it","pl":"Ten film mi się podoba.","en":"I like this film."},{"label":"How someone feels: jest + dative","pl":"Jest mi zimno.","en":"I'm cold."},{"label":"pasować: it suits someone","pl":"Ten kolor ci pasuje.","en":"This colour suits you."}],"triggers":{"prepositions":[],"verbs":["dawać / dać","kupować / kupić (komuś)","pokazywać / pokazać","mówić / powiedzieć (komuś)","pomagać / pomóc","dziękować / podziękować","podobać się","pasować (komuś)"],"other":["jest mi zimno / ciepło / smutno","Kiedy ci pasuje?"]},"endings":{"singular":{"masculine":"-owi (Tomkowi, lekarzowi); -u on a short list: bratu, panu, ojcu, kotu, psu","masculine in -a":"like feminine: tacie, koledze","feminine":"-e with a softened consonant (mamie, siostrze, córce); -i / -y after soft consonants (Ani, babci, pracy)","neuter":"-u (dziecku)"},"plural":{"masculine personal":"-om","other":"-om"},"adjective":{"singular":{"masculine":"-emu","feminine":"-ej","neuter":"-emu"},"plural":{"masculine personal":"-ym / -im","other":"-ym / -im"}}},"traps":["English says \"to Mum\"; Polish has no preposition here: Daję prezent do mamy ✗ → Daję mamie prezent ✓. do means \"to a place\".","pomagać and dziękować take the dative, not the accusative: Pomagam brata ✗ → Pomagam bratu ✓, Dziękuję pana ✗ → Dziękuję panu ✓.","With podobać się the thing you like is the subject and you are in the dative: Ja podobam ten film ✗ → Ten film mi się podoba ✓.","How you feel is jest + dative + an adverb: Jestem zimny ✗ → Jest mi zimno ✓."],"contrasts":[{"with":"accusative","rule":"The thing you give or buy is the accusative; the person who gets it is the dative.","examples":["Kupiłam książkę.","Kupiłam bratu książkę."]},{"with":"locative","rule":"Feminine nouns look the same in the dative and the locative: only the question differs (komu? / o kim?).","examples":["Daję mamie kwiaty.","Rozmawiamy o mamie."]}],"topicIds":["a2-cases-dative","a2-grammar-pronouns-in-cases"],"setTags":["dative"]},{"id":"accusative","name":"Biernik","nameEn":"Accusative","questions":"kogo? co?","level":"A1","summary":"The direct object: the person or thing the action goes to.","uses":[{"label":"Direct object","pl":"Czytam książkę.","en":"I'm reading a book."},{"label":"Ordering","pl":"Poproszę kawę.","en":"A coffee, please."},{"label":"Where to, after na","pl":"Idę na koncert.","en":"I'm going to a concert."},{"label":"Days of the week","pl":"w sobotę","en":"on Saturday"},{"label":"Plural objects: men take -ów / -y / -i, the rest = nominative","pl":"Znam tych studentów. Lubię koty.","en":"I know these students. I like cats."},{"label":"How long, and for what: na","pl":"Chciałabym pokój na trzy noce.","en":"I'd like a room for three nights. (a woman speaking)"},{"label":"Games and sports: grać w","pl":"W sobotę gram w tenisa.","en":"On Saturday I'm playing tennis."},{"label":"The person something hurts","pl":"Boli mnie głowa.","en":"I have a headache."}],"triggers":{"prepositions":["na (where to)","w (days: w sobotę)","przez","za (in … time)","o (prosić o, pytać o)","na (how long, what for: na trzy noce, coś na kaszel, ochota na)","w (games: grać w tenisa)"],"verbs":["mieć","lubić","znać","widzieć","czytać","pić","jeść","kupować","kochać","odwiedzać","boleć (Boli mnie głowa)"],"other":[]},"endings":{"singular":{"masculine (people, animals)":"-a (in -a: tata → tatę)","masculine (things)":"= nominative","feminine":"-ę (pani → panią, noc → noc)","neuter":"= nominative"},"plural":{"masculine personal":"= genitive","other":"= nominative"},"adjective":{"singular":{"masculine (people, animals)":"-ego","masculine (things)":"-y / -i","feminine":"-ą","neuter":"-e"},"plural":{"masculine personal":"-ych / -ich","other":"-e"}}},"traps":["English marks the object only by its place in the sentence. Polish needs the ending: Lubię kawę, not Lubię kawa.","Masculine people and animals take -a, like the genitive: Mam brata, Mam psa. Things do not change: Mam dom.","After nie the object switches to the genitive: Mam czas. → Nie mam czasu.","Going into a building or a town takes do + genitive, not w + accusative: Idę do szkoły, not Idę w szkołę.","In the plural only men change: Znam te studenty ✗ → Znam tych studentów ✓. Animals are like things: Lubię psy, not Lubię psów."],"contrasts":[{"with":"genitive","rule":"Positive sentence: accusative. Negated sentence: genitive.","examples":["Mam samochód.","Nie mam samochodu."]},{"with":"nominative","rule":"A feminine noun ends in -a as the subject and in -ę as the object.","examples":["Książka jest ciekawa.","Czytam książkę."]},{"with":"locative","rule":"na + accusative = where to. na + locative = where. With w, where to is usually do + genitive: Idę do szkoły, Jestem w szkole.","examples":["Idę na pocztę.","Jestem na poczcie."]}],"topicIds":["a1-cases-accusative","a2-cases-accusative-plural"],"setTags":["accusative"]},{"id":"instrumental","name":"Narzędnik","nameEn":"Instrumental","questions":"z kim? z czym?","level":"A1","summary":"Who or what someone is after być, the company you are in after z (with), and how you travel or pay.","uses":[{"label":"A job or nationality after być","pl":"Jestem studentem.","en":"I'm a student."},{"label":"Together with, after z","pl":"Poproszę kawę z mlekiem.","en":"A coffee with milk, please."},{"label":"Means of transport","pl":"Jadę do pracy autobusem.","en":"I'm going to work by bus."},{"label":"Paying","pl":"Czy mogę zapłacić kartą?","en":"Can I pay by card?"},{"label":"Together with people, in the plural","pl":"Mieszkam z rodzicami.","en":"I live with my parents."},{"label":"Interests: interesować się","pl":"Interesuję się historią.","en":"I'm interested in history."},{"label":"Where: przed, za, nad, pod, między","pl":"Kot śpi pod łóżkiem.","en":"The cat is sleeping under the bed."},{"label":"Jobs in the plural, after być","pl":"Moi rodzice są nauczycielami.","en":"My parents are teachers."}],"triggers":{"prepositions":["z (with)","przed","za (behind)","nad","pod","między"],"verbs":["być + noun (a job, a nationality, a role)","interesować się","spotykać się z"],"other":["transport: autobusem, pociągiem, samochodem","paying: kartą, gotówką"]},"endings":{"singular":{"masculine":"-em (after k, g: -iem)","feminine":"-ą","neuter":"-em (after k, g: -iem)"},"plural":{"masculine personal":"-ami","other":"-ami (a few: -mi, dziećmi)"},"adjective":{"singular":{"masculine":"-ym / -im","feminine":"-ą","neuter":"-ym / -im"},"plural":{"masculine personal":"-ymi / -imi","other":"-ymi / -imi"}}},"traps":["English uses the same form in \"I am a student\" and \"the student is here\". Polish needs the instrumental after być: Jestem student ✗ → Jestem studentem ✓.","An adjective alone after być stays in the nominative: Jestem zmęczony, not Jestem zmęczonym. A first name in an introduction stays in the nominative too: Jestem Tomek.","After to jest the noun stays in the nominative: To jest student. But: On jest studentem.","\"By bus\" has no preposition: Jadę z autobusem ✗ → Jadę autobusem ✓. z autobusem means \"together with a bus\".","\"Interested in\" is one verb with się, not a copy of English: Jestem zainteresowany w historii ✗ → Interesuję się historią ✓.","The plural ending is -ami for almost every noun: z kolegami, z koleżankami. Learn the few in -mi: z ludźmi, z dziećmi, z przyjaciółmi."],"contrasts":[{"with":"nominative","rule":"to jest + nominative names someone; być + noun says what someone is and takes the instrumental.","examples":["To jest lekarz.","On jest lekarzem."]},{"with":"genitive","rule":"z meaning with takes the instrumental; z meaning from takes the genitive.","examples":["kawa z mlekiem","Jestem z Polski."]}],"topicIds":["a1-cases-instrumental-identity","a2-cases-instrumental-full"],"setTags":["instrumental"]},{"id":"locative","name":"Miejscownik","nameEn":"Locative","questions":"o kim? o czym?","level":"A1","summary":"Where someone or something is, after w and na. The locative never stands alone: it always follows a preposition.","uses":[{"label":"Where, after w","pl":"Mieszkam w Krakowie.","en":"I live in Kraków."},{"label":"Where, after na (the na-places)","pl":"Czekam na przystanku.","en":"I'm waiting at the stop."},{"label":"Events, after na","pl":"Jestem na koncercie.","en":"I'm at a concert."},{"label":"Surfaces, after na","pl":"Telefon jest na stole.","en":"The phone is on the table."},{"label":"At home","pl":"Wieczorem jestem w domu.","en":"In the evening I'm at home."},{"label":"About: o","pl":"Rozmawiamy o nowym filmie.","en":"We're talking about the new film."},{"label":"After: po","pl":"Po pracy idę na siłownię.","en":"After work I'm going to the gym."},{"label":"Months, this / next / last …","pl":"W przyszłym tygodniu mam egzamin.","en":"I have an exam next week."},{"label":"Plural: -ach for every gender","pl":"W małych miastach jest spokojnie.","en":"It's quiet in small towns."}],"triggers":{"prepositions":["w (where)","na (where)","o (about)","po (after; around: po parku)","przy (at, by)"],"verbs":["mieszkać w / na","być w / na","pracować w / na","rozmawiać o, mówić o, myśleć o, pamiętać o","grać na (instruments)","jeździć na (rowerze, nartach)"],"other":["Gdzie? (where?)"]},"endings":{"singular":{"masculine":"-e with a softened consonant (Kraków → w Krakowie); -u after k, g, ch and soft consonants (w banku, w hotelu), and in w domu","feminine":"-e with a softened consonant (w szkole, w Polsce); -i / -y after soft consonants (w kuchni, w pracy)","neuter":"-e with a softened consonant (w kinie); -u after k, g, ch (na lotnisku, w łóżku) and after soft consonants (w mieszkaniu); -um does not change (w muzeum)"},"plural":{"masculine personal":"-ach","other":"-ach"},"adjective":{"singular":{"masculine":"-ym / -im","feminine":"-ej","neuter":"-ym / -im"},"plural":{"masculine personal":"-ych / -ich","other":"-ych / -ich"}}},"traps":["In English the noun after in or at never changes. In Polish it does: Mieszkam w Kraków ✗ → Mieszkam w Krakowie ✓.","Before -e the consonant softens: k → c (w Polsce), g → dz (w Pradze), t → ci (na poczcie), d → dzi (w ogrodzie), r → rz (w biurze), ł → l (w szkole).","dom takes -u: w domu, not w domie.","Some places take na, not w: na poczcie, na dworcu, na przystanku, na rynku, na lotnisku, na uniwersytecie.","The locative says where you are, not where you go: Idę w sklepie ✗ → Idę do sklepu ✓.","\"About\" after rozmawiać, mówić, myśleć takes the locative: Rozmawiamy o pracę ✗ → Rozmawiamy o pracy ✓. (o + accusative is for asking: pytać o drogę.)","The locative plural is -ach, the instrumental plural -ami: w sklepach, but z kolegami."],"contrasts":[{"with":"genitive","rule":"w + locative = where you are; do + genitive = where you go.","examples":["Jestem w sklepie.","Idę do sklepu."]},{"with":"accusative","rule":"na + locative = where you are; na + accusative = where you go.","examples":["Jestem na poczcie.","Idę na pocztę."]}],"topicIds":["a1-cases-locative-places","a2-cases-locative-full"],"setTags":["locative"]}],"models":[{"id":"nowy-student","gender":"masculine personal","en":"new student","singular":{"nominative":"nowy student","genitive":"nowego studenta","dative":"nowemu studentowi","accusative":"nowego studenta","instrumental":"nowym studentem","locative":"nowym studencie","vocative":"nowy studencie"},"plural":{"nominative":"nowi studenci","genitive":"nowych studentów","dative":"nowym studentom","accusative":"nowych studentów","instrumental":"nowymi studentami","locative":"nowych studentach","vocative":"nowi studenci"}},{"id":"dobry-lekarz","gender":"masculine personal","en":"good doctor","singular":{"nominative":"dobry lekarz","genitive":"dobrego lekarza","dative":"dobremu lekarzowi","accusative":"dobrego lekarza","instrumental":"dobrym lekarzem","locative":"dobrym lekarzu","vocative":"dobry lekarzu"},"plural":{"nominative":"dobrzy lekarze","genitive":"dobrych lekarzy","dative":"dobrym lekarzom","accusative":"dobrych lekarzy","instrumental":"dobrymi lekarzami","locative":"dobrych lekarzach","vocative":"dobrzy lekarze"}},{"id":"maly-kot","gender":"masculine animate","en":"small cat","singular":{"nominative":"mały kot","genitive":"małego kota","dative":"małemu kotu","accusative":"małego kota","instrumental":"małym kotem","locative":"małym kocie","vocative":"mały kocie"},"plural":{"nominative":"małe koty","genitive":"małych kotów","dative":"małym kotom","accusative":"małe koty","instrumental":"małymi kotami","locative":"małych kotach","vocative":"małe koty"}},{"id":"stary-dom","gender":"masculine inanimate","en":"old house","singular":{"nominative":"stary dom","genitive":"starego domu","dative":"staremu domowi","accusative":"stary dom","instrumental":"starym domem","locative":"starym domu","vocative":"stary domu"},"plural":{"nominative":"stare domy","genitive":"starych domów","dative":"starym domom","accusative":"stare domy","instrumental":"starymi domami","locative":"starych domach","vocative":"stare domy"}},{"id":"nowy-pokoj","gender":"masculine inanimate","en":"new room","note":"ó changes to o in every form except the nominative and accusative singular. Genitive plural: pokoi (also pokojów).","singular":{"nominative":"nowy pokój","genitive":"nowego pokoju","dative":"nowemu pokojowi","accusative":"nowy pokój","instrumental":"nowym pokojem","locative":"nowym pokoju","vocative":"nowy pokoju"},"plural":{"nominative":"nowe pokoje","genitive":"nowych pokoi","dative":"nowym pokojom","accusative":"nowe pokoje","instrumental":"nowymi pokojami","locative":"nowych pokojach","vocative":"nowe pokoje"}},{"id":"dobra-kawa","gender":"feminine","en":"good coffee","note":"In the plural: cups or kinds of coffee (Poproszę dwie kawy).","singular":{"nominative":"dobra kawa","genitive":"dobrej kawy","dative":"dobrej kawie","accusative":"dobrą kawę","instrumental":"dobrą kawą","locative":"dobrej kawie","vocative":"dobra kawo"},"plural":{"nominative":"dobre kawy","genitive":"dobrych kaw","dative":"dobrym kawom","accusative":"dobre kawy","instrumental":"dobrymi kawami","locative":"dobrych kawach","vocative":"dobre kawy"}},{"id":"nowa-lekcja","gender":"feminine","en":"new lesson","singular":{"nominative":"nowa lekcja","genitive":"nowej lekcji","dative":"nowej lekcji","accusative":"nową lekcję","instrumental":"nową lekcją","locative":"nowej lekcji","vocative":"nowa lekcjo"},"plural":{"nominative":"nowe lekcje","genitive":"nowych lekcji","dative":"nowym lekcjom","accusative":"nowe lekcje","instrumental":"nowymi lekcjami","locative":"nowych lekcjach","vocative":"nowe lekcje"}},{"id":"mala-ulica","gender":"feminine","en":"small street","singular":{"nominative":"mała ulica","genitive":"małej ulicy","dative":"małej ulicy","accusative":"małą ulicę","instrumental":"małą ulicą","locative":"małej ulicy","vocative":"mała ulico"},"plural":{"nominative":"małe ulice","genitive":"małych ulic","dative":"małym ulicom","accusative":"małe ulice","instrumental":"małymi ulicami","locative":"małych ulicach","vocative":"małe ulice"}},{"id":"dluga-noc","gender":"feminine","en":"long night","note":"A feminine noun without -a: the noun does not change in the accusative singular; only the adjective does (długą noc).","singular":{"nominative":"długa noc","genitive":"długiej nocy","dative":"długiej nocy","accusative":"długą noc","instrumental":"długą nocą","locative":"długiej nocy","vocative":"długa nocy"},"plural":{"nominative":"długie noce","genitive":"długich nocy","dative":"długim nocom","accusative":"długie noce","instrumental":"długimi nocami","locative":"długich nocach","vocative":"długie noce"}},{"id":"male-okno","gender":"neuter","en":"small window","singular":{"nominative":"małe okno","genitive":"małego okna","dative":"małemu oknu","accusative":"małe okno","instrumental":"małym oknem","locative":"małym oknie","vocative":"małe okno"},"plural":{"nominative":"małe okna","genitive":"małych okien","dative":"małym oknom","accusative":"małe okna","instrumental":"małymi oknami","locative":"małych oknach","vocative":"małe okna"}},{"id":"dobre-piwo","gender":"neuter","en":"good beer","singular":{"nominative":"dobre piwo","genitive":"dobrego piwa","dative":"dobremu piwu","accusative":"dobre piwo","instrumental":"dobrym piwem","locative":"dobrym piwie","vocative":"dobre piwo"},"plural":{"nominative":"dobre piwa","genitive":"dobrych piw","dative":"dobrym piwom","accusative":"dobre piwa","instrumental":"dobrymi piwami","locative":"dobrych piwach","vocative":"dobre piwa"}},{"id":"nowe-mieszkanie","gender":"neuter","en":"new flat","singular":{"nominative":"nowe mieszkanie","genitive":"nowego mieszkania","dative":"nowemu mieszkaniu","accusative":"nowe mieszkanie","instrumental":"nowym mieszkaniem","locative":"nowym mieszkaniu","vocative":"nowe mieszkanie"},"plural":{"nominative":"nowe mieszkania","genitive":"nowych mieszkań","dative":"nowym mieszkaniom","accusative":"nowe mieszkania","instrumental":"nowymi mieszkaniami","locative":"nowych mieszkaniach","vocative":"nowe mieszkania"}},{"id":"trudne-imie","gender":"neuter","en":"difficult name","note":"Nouns in -ę add -eni- (singular) or -on- (plural): imię → imienia, imiona.","singular":{"nominative":"trudne imię","genitive":"trudnego imienia","dative":"trudnemu imieniu","accusative":"trudne imię","instrumental":"trudnym imieniem","locative":"trudnym imieniu","vocative":"trudne imię"},"plural":{"nominative":"trudne imiona","genitive":"trudnych imion","dative":"trudnym imionom","accusative":"trudne imiona","instrumental":"trudnymi imionami","locative":"trudnych imionach","vocative":"trudne imiona"}},{"id":"male-muzeum","gender":"neuter","en":"small museum","note":"Nouns in -um do not change in the singular; only the adjective shows the case.","singular":{"nominative":"małe muzeum","genitive":"małego muzeum","dative":"małemu muzeum","accusative":"małe muzeum","instrumental":"małym muzeum","locative":"małym muzeum","vocative":"małe muzeum"},"plural":{"nominative":"małe muzea","genitive":"małych muzeów","dative":"małym muzeom","accusative":"małe muzea","instrumental":"małymi muzeami","locative":"małych muzeach","vocative":"małe muzea"}}],"trees":[{"id":"pick-case","title":"Pick the case","intro":"Think of one noun in your sentence and answer the questions about it.","start":"start","nodes":{"start":{"question":"Is there a preposition right before the noun (or before its adjective)?","help":"Prepositions are short words such as do, z, w, na, bez, dla, u.","options":[{"label":"Yes, there is a preposition","next":"preposition"},{"label":"No preposition","next":"role"}]},"preposition":{"question":"Which preposition is it?","options":[{"label":"do, od, bez, dla, u, obok, koło, naprzeciwko, blisko, niedaleko","result":["genitive"],"why":"These prepositions always take the genitive.","example":{"pl":"Idę do sklepu.","en":"I'm going to the shop."}},{"label":"z","next":"z"},{"label":"na","next":"na"},{"label":"w","next":"w"},{"label":"przez, or za meaning in … time or for (za tydzień, dziękuję za pomoc)","result":["accusative"],"why":"przez and za meaning in … time or for take the accusative: Wracam za tydzień. Dziękuję za pomoc. (za meaning behind takes the instrumental: za domem.)","example":{"pl":"Wracam za tydzień.","en":"I'm coming back in a week."}},{"label":"o, po, przy (about, after, next to)","result":["locative"],"why":"o, po and przy usually take the locative: mówić o filmie, po lekcji, przy oknie. (o meaning for, as in prosić o, takes the accusative, and so does po meaning to fetch: Idę po chleb.)","example":{"pl":"Rozmawiamy o pracy.","en":"We're talking about work."}},{"label":"przed, za (behind), pod, nad, między (in front of, behind, under, above, between)","result":["instrumental"],"why":"When they say where something is, these prepositions take the instrumental: przed domem, za kościołem, pod łóżkiem, nad morzem. Going there takes the accusative: Jedziemy nad morze, Kot wchodzi pod stół.","example":{"pl":"Czekam przed domem.","en":"I'm waiting in front of the house."}}]},"z":{"question":"What does z mean here?","options":[{"label":"from, out of (Where from?)","result":["genitive"],"why":"z meaning from takes the genitive.","example":{"pl":"Jestem z Polski.","en":"I'm from Poland."}},{"label":"with, together with (With whom? With what?)","result":["instrumental"],"why":"z meaning with takes the instrumental.","example":{"pl":"Piję kawę z mlekiem.","en":"I drink coffee with milk."}}]},"na":{"question":"Does na say where something goes, or where it is?","options":[{"label":"Where it goes (Where to?)","result":["accusative"],"why":"na + accusative = where to.","example":{"pl":"Idę na koncert.","en":"I'm going to a concert."}},{"label":"Where it is (Where?)","result":["locative"],"why":"na + locative = where.","example":{"pl":"Jestem na koncercie.","en":"I'm at a concert."}}]},"w":{"question":"What does w say here?","options":[{"label":"Where something is (Where?)","result":["locative"],"why":"w + locative = where: in a building, a town, a country.","example":{"pl":"Mieszkam w Krakowie.","en":"I live in Kraków."}},{"label":"Where someone goes: into a building, a town, a country","result":["genitive"],"why":"Going into a place usually takes do + genitive, not w: Idę do szkoły, not Idę w szkołę.","example":{"pl":"Jadę do Warszawy.","en":"I'm going to Warsaw."}},{"label":"A day of the week (on Monday …)","result":["accusative"],"why":"w + a day of the week takes the accusative. (Months and years take the locative: w maju.)","example":{"pl":"Do zobaczenia w sobotę.","en":"See you on Saturday."}},{"label":"A month or a year (in May, in 2025)","result":["locative"],"why":"w + a month or a year takes the locative.","example":{"pl":"Mam urlop w maju.","en":"I have a holiday in May."}}]},"role":{"question":"What does the noun do in the sentence?","options":[{"label":"It is the subject: the person or thing that does the action","result":["nominative"],"why":"The subject is in the nominative. (After quantity words like dużo or pięć it goes into the genitive: Pięć osób czeka.)","example":{"pl":"Mój brat pracuje w Warszawie.","en":"My brother works in Warsaw."}},{"label":"It comes after to jest or to są","result":["nominative"],"why":"After to jest / to są the noun stays in the nominative.","example":{"pl":"To jest moja siostra.","en":"This is my sister."}},{"label":"It is a noun after być saying who someone is (a job, a nationality, a role)","result":["instrumental"],"why":"być + noun takes the instrumental: Jestem lekarzem. With a first name in an introduction the nominative is usual: Jestem Tomek. An adjective after być stays in the nominative: Kawa jest gorąca.","example":{"pl":"Ona jest nauczycielką.","en":"She is a teacher."}},{"label":"It is the object of the verb: the person or thing the action goes to","next":"object"},{"label":"It says whose something is, or follows a quantity word (dużo, mało, pięć …)","result":["genitive"],"why":"Possession and quantities take the genitive.","example":{"pl":"Mam dużo pracy.","en":"I have a lot of work."}},{"label":"It is the person who receives something (To whom?)","result":["dative"],"why":"The receiver of a gift, a message or help is in the dative.","example":{"pl":"Daję mamie kwiaty.","en":"I'm giving my mum flowers."}},{"label":"It goes with pomagać, dziękować, podobać się, pasować or jest … zimno (the person who is helped, thanked, likes it, is suited or feels it)","result":["dative"],"why":"These verbs and phrases take the person in the dative: Pomagam bratu. Dziękuję panu. Podoba mi się. Pasuje ci. Jest mi zimno.","example":{"pl":"Ten film bardzo mi się podoba.","en":"I really like this film."}},{"label":"It is a tool or a means of transport (With what? By what?)","result":["instrumental"],"why":"Tools and means of transport without a preposition take the instrumental.","example":{"pl":"Jadę autobusem.","en":"I'm going by bus."}},{"label":"You are speaking to someone directly","result":["vocative"],"why":"Addressing someone takes the vocative.","example":{"pl":"Dzień dobry, panie profesorze!","en":"Good morning, professor!"}}]},"object":{"question":"Which kind of verb is it?","help":"A few verbs take another case for their object. Check them first.","options":[{"label":"szukać, słuchać, potrzebować, używać, bać się, uczyć się","result":["genitive"],"why":"These verbs take the genitive, also in a positive sentence: Szukam klucza. Uczę się polskiego.","example":{"pl":"Szukam klucza.","en":"I'm looking for the key."}},{"label":"pomagać, dziękować, or the person after dawać (komu?)","result":["dative"],"why":"The person you help, thank or give something to is in the dative, also after nie. The thing you give stays in the accusative: Daję mamie kwiaty.","example":{"pl":"Pomagam bratu.","en":"I'm helping my brother."}},{"label":"interesować się (be interested in)","result":["instrumental"],"why":"interesować się takes the instrumental: Interesuję się sportem.","example":{"pl":"Ola interesuje się historią.","en":"Ola is interested in history."}},{"label":"Another verb (mieć, lubić, kupować, czytać …)","next":"negation"}]},"negation":{"question":"Is the verb negated with nie?","options":[{"label":"Yes, there is nie before the verb","result":["genitive"],"why":"After nie the direct object switches from the accusative to the genitive.","example":{"pl":"Nie lubię kawy.","en":"I don't like coffee."}},{"label":"No, the sentence is positive","result":["accusative"],"why":"Most verbs take a direct object in the accusative.","example":{"pl":"Kupuję gazetę i kawę.","en":"I'm buying a newspaper and coffee."}}]}}},{"id":"w-or-na","title":"w or na?","intro":"For a place: which little word do you need, and which case follows it?","start":"start","nodes":{"start":{"question":"What kind of place is it?","options":[{"label":"Most buildings, rooms and shops: sklep, bank, szkoła, kino, kuchnia","answer":{"title":"w","text":"Most buildings and rooms take w. Where you are: w + locative. Where you go: do + genitive.","examples":[{"pl":"Jestem w sklepie.","en":"I'm in the shop."},{"pl":"Idę do sklepu.","en":"I'm going to the shop."}]}},{"label":"A town, a city or a country","answer":{"title":"w","text":"Towns and most countries take w. Where you are: w + locative. Where you go: do + genitive.","examples":[{"pl":"Mieszkam w Krakowie.","en":"I live in Kraków."},{"pl":"Jadę do Polski.","en":"I'm going to Poland."}]}},{"label":"Home","answer":{"title":"w domu / do domu","text":"dom takes -u in both: w domu (at home), do domu (home, when you go there).","examples":[{"pl":"Jestem w domu.","en":"I'm at home."},{"pl":"Idę do domu.","en":"I'm going home."}]}},{"label":"A na-place (poczta, dworzec, lotnisko, uniwersytet), a stop, a square, a street, a surface or an event","next":"na"}]},"na":{"question":"Which one is it?","options":[{"label":"poczta, dworzec, przystanek, rynek, lotnisko, uniwersytet","answer":{"title":"na","text":"These places take na. Learn them as a list. Where you are: na + locative. Where you go: na + accusative.","examples":[{"pl":"Czekam na dworcu.","en":"I'm waiting at the station."},{"pl":"Jadę na dworzec.","en":"I'm going to the station."}]}},{"label":"An event or a meal: a concert, a lesson, a coffee","answer":{"title":"na","text":"Events take na. Where you are: na + locative. Where you go: na + accusative.","examples":[{"pl":"Jestem na koncercie.","en":"I'm at a concert."},{"pl":"Idziemy na kawę.","en":"We're going for a coffee."}]}},{"label":"A surface or a street: a table, a shelf, a street","answer":{"title":"na","text":"On a surface or in a street: na + locative.","examples":[{"pl":"Telefon jest na stole.","en":"The phone is on the table."},{"pl":"Samochód jest na ulicy.","en":"The car is in the street."}]}}]}}},{"id":"go","title":"Which verb of going?","intro":"English \"go\" (and \"fly\") is nine verbs in Polish at A2: iść, jechać, lecieć for one trip, chodzić, jeździć, latać for a habit, and pójść, pojechać, polecieć for one finished trip. Answer two or three questions. (Verbs like przyjść and wyjść come at B1.)","start":"start","nodes":{"start":{"question":"Is it one trip, or something regular?","options":[{"label":"One trip, in one direction","next":"when"},{"label":"A habit or a repeated trip (codziennie, często, w soboty), or moving in general (walking, cycling, flying as an activity)","next":"habit"}]},"when":{"question":"How does the sentence look at the trip?","options":[{"label":"Now or planned (Teraz idę…, Jutro lecę…), or \"was going\" in the past while something else happened","next":"one"},{"label":"As one whole trip that happened or will happen: went, has gone, will go","next":"done"}]},"one":{"question":"How are you travelling?","options":[{"label":"On foot, or to an everyday place in town when the sentence names no vehicle","answer":{"title":"iść","text":"One trip on foot: iść (idę, idziesz, idą). Past \"was going\": szedłem / szłam.","examples":[{"pl":"Teraz idę do sklepu, zaraz wracam.","en":"I'm going to the shop now, I'll be right back."},{"pl":"Kiedy szedłem do domu, zaczął padać deszcz.","en":"While I was walking home, it started to rain."}]}},{"label":"By car, bus, tram, train or bike (also to work or school), or to another town","answer":{"title":"jechać","text":"One trip with a vehicle: jechać (jadę, jedziesz, jadą). The vehicle is in the instrumental: autobusem, pociągiem.","examples":[{"pl":"Jutro jadę do Gdańska.","en":"I'm going to Gdańsk tomorrow."},{"pl":"Kiedy jechałam do pracy, zadzwoniła mama.","en":"While I was on my way to work, Mum called."}]}},{"label":"By plane","answer":{"title":"lecieć","text":"One flight: lecieć (lecę, lecisz, lecą).","examples":[{"pl":"Jutro lecę do Londynu.","en":"I'm flying to London tomorrow."},{"pl":"Samolot leci do Rzymu.","en":"The plane is flying to Rome."}]}}]},"habit":{"question":"How do you travel?","options":[{"label":"On foot, or to everyday places in town when the sentence names no vehicle","answer":{"title":"chodzić","text":"A habit on foot, or walking in general: chodzić (chodzę, chodzisz, chodzą). Also \"can walk\": Nasz syn już chodzi.","examples":[{"pl":"W soboty chodzę na basen.","en":"On Saturdays I go swimming."},{"pl":"W niedziele lubimy chodzić po parku.","en":"On Sundays we like walking around the park."}]}},{"label":"By vehicle or bike (also to work or school), or to other towns","answer":{"title":"jeździć","text":"A habit with a vehicle, or riding in general: jeździć (jeżdżę, jeździsz, jeżdżą). Watch the spelling: jeżdżę.","examples":[{"pl":"Codziennie jeżdżę do pracy rowerem.","en":"I cycle to work every day."},{"pl":"Lubię jeździć na rowerze.","en":"I like cycling."}]}},{"label":"By plane, or flying in general","answer":{"title":"latać","text":"Flying as a habit or an activity: latać (latam, latasz, latają).","examples":[{"pl":"Moja siostra często lata do Londynu.","en":"My sister often flies to London."},{"pl":"Nie lubię latać samolotem.","en":"I don't like flying."}]}}]},"done":{"question":"How did or will you travel?","options":[{"label":"On foot, or to an everyday place in town when no vehicle is named","answer":{"title":"pójść","text":"One finished trip on foot: pójść. Past poszedł / poszła, future pójdę. For a plan both work: Jutro idę / pójdę. A past trip there and back: Wczoraj byłem w kinie.","examples":[{"pl":"Paweł poszedł do domu.","en":"Paweł went home."},{"pl":"Jutro pójdę do lekarza.","en":"I'll go to the doctor's tomorrow."}]}},{"label":"By vehicle (also to work or school), or to another town or country","answer":{"title":"pojechać","text":"One finished trip with a vehicle: pojechać. Past pojechał / pojechała, future pojadę. For a plan both work: Jutro jadę / pojadę.","examples":[{"pl":"W zeszłym roku pojechaliśmy do Włoch.","en":"Last year we went to Italy."},{"pl":"W sierpniu pojedziemy do Gdańska.","en":"In August we'll go to Gdańsk."}]}},{"label":"By plane","answer":{"title":"polecieć","text":"One finished flight: polecieć. Past poleciał / poleciała, future polecę.","examples":[{"pl":"Ania poleciała do Londynu.","en":"Ania has flown to London."},{"pl":"W sobotę polecimy do Paryża.","en":"On Saturday we'll fly to Paris."}]}}]}}},{"id":"aspect","title":"Imperfective or perfective?","intro":"Most verbs come in pairs: robić / zrobić, kupować / kupić. Answer the questions about your sentence to choose the verb of the pair. (być, mieć, znać, wiedzieć have no perfective partner.)","start":"start","nodes":{"start":{"question":"When is the action?","options":[{"label":"Now, at the moment of speaking, or as a present habit","answer":{"title":"Imperfective (robić)","text":"Only imperfective verbs have a present tense. A perfective verb in a present form means the future: zrobię = I'll do.","examples":[{"pl":"Teraz robię obiad.","en":"I'm making lunch now."},{"pl":"Codziennie czytam gazetę.","en":"I read the paper every day."}]}},{"label":"In the past or in the future","next":"kind"},{"label":"It is a command or a request","next":"command"}]},"kind":{"question":"What does the sentence say about the action?","options":[{"label":"One finished action with a result (już, w końcu), or one event in a chain of events","answer":{"title":"Perfective (zrobić)","text":"One result, or one step after another: perfective. Past napisałam; future napiszę, with no będę.","examples":[{"pl":"W końcu napisałam ten e-mail.","en":"I finally wrote that email."},{"pl":"Wstałem, zjadłem śniadanie i poszedłem do pracy.","en":"I got up, ate breakfast and went to work."}]}},{"label":"A habit or a repeated action (codziennie, często, zawsze, zwykle)","answer":{"title":"Imperfective (robić)","text":"Repeated actions take the imperfective. Future: będę + infinitive.","examples":[{"pl":"Codziennie kupowałam chleb.","en":"I bought bread every day."},{"pl":"Od poniedziałku będę biegać codziennie.","en":"From Monday I'm going to run every day."}]}},{"label":"How long, the process (\"was doing\", \"will be doing\": cały dzień, długo), or just the activity with no result in view (Co robiłeś wczoraj? — Oglądałem telewizję.)","answer":{"title":"Imperfective (robić)","text":"Duration and process take the imperfective. Never będę + a perfective verb.","examples":[{"pl":"Cały dzień gotowałem.","en":"I cooked all day."},{"pl":"Jutro będę pracować w domu.","en":"Tomorrow I'll be working at home."}]}},{"label":"The background while something else happened","answer":{"title":"Imperfective (robić)","text":"The background is imperfective; the event that cuts in is perfective.","examples":[{"pl":"Kiedy czytałam, zadzwonił telefon.","en":"While I was reading, the phone rang."}]}}]},"command":{"question":"What kind of command is it?","options":[{"label":"Do it once (a request with a result)","answer":{"title":"Perfective (zrobić)","text":"One request, one result: usually the perfective imperative.","examples":[{"pl":"Zamknij okno, proszę.","en":"Close the window, please."},{"pl":"Zadzwoń do mnie jutro.","en":"Call me tomorrow."}]}},{"label":"Do it regularly, or keep doing it","answer":{"title":"Imperfective (robić)","text":"Something regular or ongoing: the imperfective imperative.","examples":[{"pl":"Czytaj codziennie po polsku.","en":"Read in Polish every day."}]}},{"label":"Don't do it","answer":{"title":"Imperfective (robić)","text":"\"Don't\" almost always takes the imperfective, and the object goes into the genitive.","examples":[{"pl":"Nie rób tego!","en":"Don't do that!"},{"pl":"Nie otwieraj okna.","en":"Don't open the window."}]}}]}}}],"aspect":{"title":"Aspect and tense on one timeline","summary":"Most Polish verbs come in pairs. The imperfective verb looks at the action as a process or a habit; the perfective verb looks at one finished result. Together they give five forms.","note":"A perfective verb has no present tense: przeczyta looks like a present form but means the future.","verb":{"imperfective":"czytać","perfective":"przeczytać","en":"to read"},"forms":[{"id":"present","name":"Present","aspect":"imperfective","form":"czyta","summary":"Happening now, or as a habit. Only imperfective verbs have a present tense.","scene":{"label":"Now","description":"The reading is going on at the moment of speaking.","elements":[{"kind":"range","from":-0.2,"to":0.2,"label":"in progress"}]},"example":{"pl":"Ola czyta książkę.","en":"Ola is reading a book."}},{"id":"past-imperfective","name":"Past","aspect":"imperfective","form":"czytała","summary":"A process in the past: how long it went on, or what was happening. It does not say if it was finished.","scene":{"label":"Process in the past","description":"The reading went on for some time yesterday; we do not know if Ola finished the book.","elements":[{"kind":"range","from":-0.85,"to":-0.35,"label":"process"}]},"example":{"pl":"Wczoraj Ola czytała książkę przez dwie godziny.","en":"Yesterday Ola spent two hours reading a book."}},{"id":"past-perfective","name":"Past","aspect":"perfective","form":"przeczytała","summary":"One finished action with a result: the whole book is read.","scene":{"label":"Result in the past","description":"At one point in the past the reading was finished; the result is there.","elements":[{"kind":"result","at":-0.45,"label":"done"}]},"example":{"pl":"Ola już przeczytała tę książkę.","en":"Ola has already read this book."}},{"id":"future-imperfective","name":"Future","aspect":"imperfective","form":"będzie czytać","summary":"A process in the future: będzie + the infinitive (or + the past-tense form that agrees with the subject: będzie czytała / będzie czytał).","scene":{"label":"Process in the future","description":"Tomorrow evening the reading will go on for some time.","elements":[{"kind":"range","from":0.35,"to":0.85,"label":"process"}]},"example":{"pl":"Jutro Ola będzie czytać cały wieczór.","en":"Tomorrow Ola will be reading all evening."}},{"id":"future-perfective","name":"Future","aspect":"perfective","form":"przeczyta","summary":"One finished result in the future, formed like a present tense.","scene":{"label":"Result in the future","description":"By Friday the reading will be finished.","elements":[{"kind":"result","at":0.6,"label":"done"}]},"example":{"pl":"Ola przeczyta tę książkę do piątku.","en":"Ola will have read this book by Friday."}}]}};
